import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Features from './components/Features';
import Guide from './components/Guide';
import Privacy from './components/Privacy';
import Contact from './components/Contact';
import Footer from './components/Footer';
import { Language } from './types';
import { CONTENT } from './constants';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>(Language.VI);

  const toggleLang = () => {
    setLang(prev => prev === Language.VI ? Language.EN : Language.VI);
  };

  const currentContent = CONTENT[lang];

  return (
    <HashRouter>
      <ScrollToTop />
      <div className="min-h-screen bg-white font-sans text-slate-900 flex flex-col">
        <Navbar 
          lang={lang} 
          toggleLang={toggleLang} 
          content={currentContent.nav} 
        />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<Hero content={currentContent.hero} />} />
            <Route path="/intro" element={<Features content={currentContent.intro} />} />
            <Route path="/guide" element={<Guide content={currentContent.guide} />} />
            <Route path="/privacy" element={<Privacy content={currentContent.privacy} />} />
            <Route path="/contact" element={<Contact content={currentContent.contact} />} />
          </Routes>
        </main>
        <Footer content={currentContent.footer} />
      </div>
    </HashRouter>
  );
};

export default App;

